import { ChangeDetectionStrategy, Component, input, output, signal } from '@angular/core';
import { DsButtonComponent, DsCardComponent, DsInputComponent } from '@ds/ui';
import { MemberRowComponent } from './member-row.component';
import { Member, TeamMembersVm } from './team-members.models';

// Figma: Screens / Team members / default  (node 4:11)
// Generated by Ship to Frontend. Presentational only: data comes in through `vm`,
// user intent goes out through outputs. Frontend connects `vm` to the real API.
@Component({
  selector: 'app-team-members-page',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [DsButtonComponent, DsCardComponent, DsInputComponent, MemberRowComponent],
  template: `
    <header class="header">
      <div class="title">
        <h1>Team members</h1>
        <p>Manage who has access to the Acme workspace.</p>
      </div>
      <ds-button variant="primary" size="md" (pressed)="inviteMember.emit()">Invite member</ds-button>
    </header>

    <div class="stats">
      <ds-card title="12 active" description="Members with access today" />
      <ds-card title="3 pending" description="Invites waiting for a response" />
      <ds-card title="1 suspended" description="Access paused by an admin" />
    </div>

    <form class="invite" (submit)="$event.preventDefault(); submitInvite()">
      <ds-input
        class="invite__email"
        type="email"
        label="Invite by email"
        placeholder="teammate@acme.io"
        hint="They will get an email with a link to join."
        state="default"
        [(value)]="inviteEmail" />
      <ds-button variant="secondary" size="md" type="submit">Send invite</ds-button>
    </form>

    <section class="members" aria-label="Members">
      @for (member of vm().members; track member.id) {
        <app-member-row [member]="member" (manage)="manage.emit($event)" />
      }
    </section>
  `,
  styleUrl: './team-members.page.scss',
})
export class TeamMembersPage {
  readonly vm = input.required<TeamMembersVm>();

  readonly inviteMember = output<void>();
  readonly invite = output<string>();
  readonly manage = output<Member>();

  protected readonly inviteEmail = signal('');

  protected submitInvite(): void {
    const email = this.inviteEmail().trim();
    if (email) this.invite.emit(email);
  }
}
